"""Content-level adjudication of captured index blobs; retain initial finding separately."""
from pathlib import Path
import collections,csv,hashlib,io,json,re,subprocess,tempfile,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[3];HERE=Path(__file__).parent
snapshot=HERE/'staged_semantic_inventory_guarded.json'
j=json.loads(snapshot.read_text());by={r['path']:r for r in j['blob_inventory']}
blob=lambda name:subprocess.check_output(['git','cat-file','blob',by[name]['blob_oid']],cwd=ROOT)
sha=lambda b:hashlib.sha256(b).hexdigest()
private=json.loads((ROOT/'task2/evidence/research_data/local_only_manifest_current.json').read_text())['files']
private_paths={x['path'] for x in private};private_hashes={x['sha256'] for x in private}
assert not private_paths & set(by)
aggregate_receipt_aliases={'task2/evidence/research_data/public_fetch_exact_network_verified.json','task2/evidence/research_data/public_fetch_network_verified.json','task2/evidence/research_data/public_fetch_receipt.json'}
content_aliases=[r for r in by.values() if r['sha256'] in private_hashes]
assert {r['path'] for r in content_aliases}<=aggregate_receipt_aliases
for r in content_aliases:
    receipt=json.loads(blob(r['path']));assert 'cities' in receipt and 'archive_sha256' in receipt
    assert all('teacher_comparison' in x for x in receipt['cities'].values())
assert 'task2/results/evolution/km_timing/inner_hour18_batchseed2024_M2.json' not in by
allowed_model_keys={'V','NV','curve','td','episodes','Q','N','A','B','NA','NB'}
npz_review=[]
for r in j['npz']:
 if r['path']=='task2/results/evolution/basic/basic_synthetic_od.npz':
  assert set(r['arrays'])=={'drv','o_xy','d_xy','pickup','fare'}
  label='pure synthetic OD arrays, generated by documented seeded basic example'
 else:
  assert set(r['arrays'])<=allowed_model_keys and {'V','NV','td','episodes'}<=set(r['arrays'])
  assert all(k not in r['arrays'] for k in ['drivers','origin_source_row','samples','genes','pairs'])
  label='Q/Double learned tables and per-training-episode aggregate learning logs; no sampled orders/drivers'
 npz_review.append(dict(path=r['path'],classification=label))
for r in j['csv']:
 assert not ({'userId','venueId','source_row','origin_source_row','destination_source_row','latitude','longitude','ox','oy','dx','dy','x','y'} & set(r['columns']))
 rows=list(csv.DictReader(io.StringIO(blob(r['path']).decode())))
 if 'matches' in r['columns']:assert all(x['matches'].startswith('matches/') and x['matches'].endswith('.json') for x in rows)
risks=collections.Counter(r['path'] for r in j['content_risks']);adjudications=[]
for name,count in risks.items():
 if name=='task2/evidence/independent_package/content_probe.json':reason='Only file names, array shapes, counts/rank/error metadata of the earlier private-record risk probe; no array elements or reconstructed fares.'
 elif name.startswith('task2/evidence/research_data/'):
  assert Path(name).name in {'author_rounding_diagnostic_aggregate.json','data_audit.json','public_fetch_exact_network_verified.json','public_fetch_network_verified.json','public_fetch_receipt.json'}
  reason='Coordinate-named fields are missing/difference counts or maximum conversion error, plus city-level coordinate ranges; no per-check-in values.'
 elif name.startswith('task2/results/evolution/basic/basic_nsga2_seed'):
  reason='Assignment membership and objectives refer only to the public pure synthetic basic OD input.'
 elif name.startswith('task2/results/evolution/runs/baseline_dtlz2_integer_teacher_'):
  reason='Genes belong to mathematical DTLZ2 benchmark, with no real records or membership to a real batch.'
 else:raise AssertionError('Unadjudicated record-valued field '+name)
 adjudications.append(dict(path=name,flag_count=count,reason=reason))
# Read and check every staged synthetic online input, rather than accepting its extension.
synthetic_inputs=[]
for name in by:
 if re.match(r'task2/results/online/(?:development_v1|confirmation_v1)/instances/.*\.json$',name):
  v=json.loads(blob(name));assert set(v)=={'workers','requests','config'};assert isinstance(v['config'],dict)
  synthetic_inputs.append(name)
 elif name.startswith('task2/results/online/threshold_diagnosis_v1/inputs/'):
  v=json.loads(blob(name));assert v['provenance']['identity']=='synthetic_development'
  synthetic_inputs.append(name)
assert len(synthetic_inputs)==125
assert not any(name.startswith('task2/results/online/foursquare_proxy_v1/inputs/') or name.startswith('task2/results/online/foursquare_proxy_v1/matches/') for name in by)
# All64 copied logs are compared with both the recorded and real original bytes.
logmap=json.loads(blob('task2/evidence/log_distribution_copies.json'))['files'];log_review=[];excluded_build_logs=[]
for r in logmap:
 name=r['public_text_copy']
 if name not in by:
  assert '/report_source_01/build/source/' in name
  b=(ROOT/name).read_bytes();excluded_build_logs.append(name)
 else:b=blob(name)
 assert sha(b)==r['sha256']==sha((ROOT/r['original_ignored_path']).read_bytes())
 log_review.append(dict(path=name,staged=name in by,bytes=len(b),sha256=sha(b)))
assert len(log_review)==64
record_re=re.compile(r'^\s*\d+\s*[,\t]\s*[0-9a-fA-F]{24}\b',re.M)
venue_re=re.compile(r'(?<![0-9a-fA-F])[0-9a-fA-F]{24}(?![0-9a-fA-F])')
for r in j['logs']:
 text=blob(r['path']).decode(errors='replace');assert not record_re.search(text) and not venue_re.search(text),r['path']
# Inspect non-JSON stdout as well; it is the aggregate data-audit rendering.
stdout_name='task2/evidence/research_data/data_prepare.stdout'
assert json.loads(blob(stdout_name))['NYC']['proxy_trips']==25550
# Vector origin layers contain at most64 cell markers per group, never3000 individual origins.
svg_grid=[]
for name in ['task2/figures/formal/rl_value_maps.svg','task2/figures/candidates/rl_value_maps.svg']:
 root=ET.fromstring(blob(name));groups=[]
 for g in root.iter():
  if g.attrib.get('id','').startswith('PathCollection_'):
   npath=sum(x.tag.endswith('path') for x in g.iter());nuse=sum(x.tag.endswith('use') for x in g.iter());assert npath<=64 and nuse<=64
   groups.append(dict(id=g.attrib['id'],paths=npath,uses=nuse))
 svg_grid.append(dict(path=name,groups=groups))
assert all(not a['record_file_members'] for a in j['archives'])
# Verify the already-public aggregate timing corresponds to the locally retained raw recompute.
rawpath=ROOT/'task2/results/evolution/km_timing/inner_hour18_batchseed2024_M2.json';raw=json.loads(rawpath.read_text())
pub=json.loads(blob('task2/public_results/evolution/metrics.json'))
r=next(r for r in pub['rows'] if r.get('timing_recompute_sha256')==sha(rawpath.read_bytes()))
assert r['runtime']==r['total_runtime']==raw['solve_seconds'] and r['n_eval']==raw['objective_evals']==41
# Text-only privacy scan of stagedPDFs; visual acceptance is inherited by exacthash, not relabeled new viewing.
pdfs=[]
with tempfile.TemporaryDirectory(prefix='dispatch_stage_pdf_text_') as folder:
 for name in sorted(n for n in by if n.endswith('.pdf')):
  p=Path(folder)/'current.pdf';p.write_bytes(blob(name))
  t=subprocess.check_output(['pdftotext','-layout',str(p),'-']).decode(errors='replace')
  assert not record_re.search(t) and not venue_re.search(t),name
  pdfs.append(dict(path=name,text_chars=len(t),text_sha256=sha(t.encode())))
result=dict(status='PASS_IN_STATED_PUBLICATION_SCOPE',reviewer='/root/reinforcement',independence='Independent ofrootNotebook/report/publication-filterauthor. This is content/package integration review; earlier RL implementation/figure author checks are not reclassified as independent mathematics.',scope='All captured staged blob bytes actually read.39NPZ arrays,11CSV schemas/everyrow,recursiveJSON record flags,5Notebook outputs,125synthetic inputschemas,31SVG/archive structure and41PDF textchecked. All64log copies compare with original bytes:62staged and2excluded build-cache copies; every stagedtextlog scanned (count below). Earlier exact34page200dpi compile pixel equivalence andR visualreview inherited, not newlyviewed/compiled.',snapshot=str(snapshot.relative_to(ROOT)),snapshot_sha256=sha(snapshot.read_bytes()),staged_set_sha256=j['staged_set_sha256'],files=j['files'],bytes=j['bytes'],initial_finding=dict(path='task2/results/evolution/km_timing/inner_hour18_batchseed2024_M2.json',retained_locally=True,excluded_from_this_snapshot=True,evidence='task2/evidence/independent_package/staged_sensitive_addendum.json'),local_only_path_intersections=0,raw_sensitive_content_hash_intersections=0,aggregate_receipt_content_aliases=[dict(path=r['path'],sha256=r['sha256'],classification='Allowed provenance receipt, also copied inside excluded author input directory; city aggregate counts/conversion errors/hashes only') for r in content_aliases],npz=npz_review,csv=j['csv'],record_flag_adjudications=adjudications,synthetic_online_inputs=len(synthetic_inputs),copied_logs=log_review,excluded_build_log_copies=excluded_build_logs,total_staged_text_logs=len(j['logs']),notebooks=j['notebooks'],origin_svg_grid_layers=svg_grid,archives=j['archives'],pdf_text=pdfs,timing_aggregate=dict(raw_sha256=sha(rawpath.read_bytes()),runtime_equal=True,n_eval_equal=True,public_membership_absent=True),source_package_inheritance=dict(original_compile='task2/evidence/independent_package/report_source_01/compile_comparison.json',current_package_asset_identity='task2/evidence/independent_integration_index/result.json',actual_page_visual_review='task2/evidence/independent_report_review/pdf_final_review.json',scope='Original0215ZIP actuallycompiled in isolation;26+8 pages fulltext and200dpipixels exact. Currentc386ZIP has same81members and onlyprovenancesources.json/package-manifest changes, independently checked byEA. No newcompile or newpageview claimed.'),limits='Automated full-byte/schema/text scan plus manual semantic adjudication of flagged content; not proof against arbitrary steganography. This receipt covers the recordedindex snapshot. Subsequent additions/changes need explicit bounded extension review. ExternalGPT/userreview andteacher submission remain separate.')
(HERE/'staged_semantic_review.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:result[k] for k in ['status','staged_set_sha256','files','bytes','local_only_path_intersections','raw_sensitive_content_hash_intersections','synthetic_online_inputs','total_staged_text_logs']},indent=2))
